  const [organization,setOrganization]=useState({name:user.organizationName,operationsEmail:''}),[message,setMessage]=useState('');
  useEffect(()=>{api<{name:string;operationsEmail?:string}>('/organization').then(org=>setOrganization({name:org.name,operationsEmail:org.operationsEmail||''}))},[]);
